CREATE OR REPLACE FUNCTION public.internal_funds_enabled()
RETURNS boolean
LANGUAGE sql
STABLE
SECURITY DEFINER
SET search_path = public
AS $$
  SELECT COALESCE((
    SELECT ft.is_enabled
    FROM public.feature_toggles AS ft
    WHERE ft.feature_key = 'internal_funds'
    ORDER BY ft.updated_at DESC
    LIMIT 1
  ), false);
$$;

